function AdminPanel({user,db,reload,onHome,onLogout,notify}){
  const [section,setSection]=useState(user.role==='admin'?'users':'quizzes');const [editing,setEditing]=useState(null);const [nationalEditing,setNationalEditing]=useState(null);const [mobile,setMobile]=useState(false);
  const players=rankRows(db.players);
  const active=db.quizzes.filter(q=>q.status==='active').length;
  const [pending,setPending]=useState(false);
  const mutate=async(path,method,data)=>{if(pending)return null;setPending(true);try{const result=await api(path,{method,data});await reload();return result}catch(e){notify(e.message);return null}finally{setPending(false)}};
  const toggle=async id=>{const q=db.quizzes.find(q=>q.id===id);if(await mutate('/api/quizzes/'+id,'PUT',{...q,status:q.status==='active'?'passive':'active'}))notify('Test holati yangilandi')};
  const remove=async id=>{if(!confirm('Bu test va uning natijalari o‘chirilsinmi?'))return;if(await mutate('/api/quizzes/'+id,'DELETE'))notify('Test o‘chirildi')};
  const resetResults=async()=>{if(confirm('O‘z testlaringizning natijalari tozalansinmi?')&&await mutate('/api/results/reset','POST'))notify('Natijalar tozalandi')};
  const activateRace=async config=>{if(db.race?.active&&!confirm('Joriy poyga yopilib, yangi poyga ochilsinmi?'))return;if(await mutate('/api/race/activate','POST',config))notify('1v1 poyga ochildi. O‘quvchilar bitta ekranda qatnashishi mumkin.')};
  const stopRace=async()=>{if(confirm('1v1 poyga yopilsinmi?')&&await mutate('/api/race/stop','POST'))notify('1v1 poyga yopildi.')};
  const setTypingStatus=async active=>{if(await mutate('/api/typing/status','POST',{active}))notify(active?'Matn terish mashqi o‘quvchilar uchun ochildi.':'Matn terish mashqi yopildi.')};
  const resetTyping=async()=>{if(confirm('Matn terish natijalari tozalansinmi?')&&await mutate('/api/typing/results/reset','POST'))notify('Matn terish natijalari tozalandi.')};
  const saveLesson=async lesson=>{const path=lesson.id?'/api/lessons/'+lesson.id:'/api/lessons',result=await mutate(path,lesson.id?'PUT':'POST',lesson);if(result)notify('Darslik saqlandi.');return result};
  const removeLesson=async id=>{if(confirm('Bu darslik o‘chirilsinmi?')&&await mutate('/api/lessons/'+id,'DELETE'))notify('Darslik o‘chirildi.')};
  const addPack=async pack=>{const result=await mutate('/api/quizzes','POST',{...structuredClone(pack),pin:String(Math.floor(100000+Math.random()*900000)),status:'passive',title:pack.title+' (nusxa)'});if(result)setEditing(result.quiz.id)};
  const saveNational=async value=>{const exists=!!value.id,path=exists?`/api/national/sections/${value.id}`:'/api/national/sections',result=await mutate(path,exists?'PUT':'POST',value);if(result){setNationalEditing(null);notify(user.role==='admin'&&value.requestPublic?'Bo‘lim ommaga chiqarildi.':value.requestPublic?'Bo‘lim administrator tasdig‘iga yuborildi.':'Bo‘lim qoralama sifatida saqlandi.')}return result};
  const reviewNational=async(id,decision)=>{if(await mutate(`/api/national/sections/${id}/review`,'POST',{decision}))notify(decision==='approved'?'Bo‘lim tasdiqlandi va ommaga chiqarildi.':'Bo‘lim rad etildi.')};
  const removeNational=async id=>{if(confirm('Bu milliy test bo‘limi o‘chirilsinmi?')&&await mutate(`/api/national/sections/${id}`,'DELETE'))notify('Bo‘lim o‘chirildi.')};
  if(editing!==null)return <QuizEditor quiz={editing==='new'?null:db.quizzes.find(q=>q.id===editing)} saving={pending} onCancel={()=>setEditing(null)} onSave={async quiz=>{const exists=db.quizzes.some(q=>q.id===quiz.id);if(await mutate(exists?'/api/quizzes/'+quiz.id:'/api/quizzes',exists?'PUT':'POST',quiz)){setEditing(null);notify('Test saqlandi')}}}/>;
  if(nationalEditing!==null)return <NationalSectionEditor section={nationalEditing==='new'?null:(db.nationalSections||[]).find(item=>item.id===nationalEditing)} role={user.role} saving={pending} onCancel={()=>setNationalEditing(null)} onSave={saveNational}/>;
  return <div className="admin-shell">
    <aside className={mobile?'open':''}><div className="aside-brand"><Brand light/><button onClick={()=>setMobile(false)}><X/></button></div><nav>{user.role==='admin'&&<button className={section==='users'?'selected':''} onClick={()=>{setSection('users');setMobile(false)}}><Users/> Foydalanuvchilar</button>}<button className={section==='quizzes'?'selected':''} onClick={()=>{setSection('quizzes');setMobile(false)}}><LayoutDashboard/> Sinf testlarim</button><button className={section==='national'?'selected':''} onClick={()=>{setSection('national');setMobile(false)}}><GraduationCap/> Milliy testlar</button><button className={section==='codes'?'selected':''} onClick={()=>{setSection('codes');setMobile(false)}}><Code2/> Ommaviy kodlar</button><button className={section==='lessons'?'selected':''} onClick={()=>{setSection('lessons');setMobile(false)}}><BookOpen/> Darsliklarim</button><button className={section==='results'?'selected':''} onClick={()=>{setSection('results');setMobile(false)}}><Trophy/> Jonli reyting</button><button className={section==='race'?'selected':''} onClick={()=>{setSection('race');setMobile(false)}}><Flag/> 1v1 poyga</button><button className={section==='typing'?'selected':''} onClick={()=>{setSection('typing');setMobile(false)}}><Keyboard/> Matn terish</button></nav><div className="aside-bottom"><button onClick={onHome}><Home/> Saytni ko‘rish</button><button onClick={onLogout}><LogOut/> Chiqish</button></div></aside>
    <div className="admin-main"><header><button className="menu-btn" onClick={()=>setMobile(true)}><Menu/></button><div><small>{user.role==='admin'?'ADMINISTRATOR PANELI':'O‘QITUVCHI PANELI'}</small><h1>{section==='users'?'Foydalanuvchilar statistikasi':section==='quizzes'?'Sinf testlarini boshqarish':section==='national'?'Milliy test bo‘limlari':section==='codes'?'Ommaviy testlar katalogi':section==='lessons'?'Darsliklarni boshqarish':section==='results'?'Jonli natijalar':section==='race'?'1v1 bilim poygasi':'Matn terish mashqlari'}</h1></div><div className="admin-user"><span>{user.name.slice(0,2).toUpperCase()}</span><div><b>{user.name}</b><small>{user.role==='admin'?'Administrator':'O‘qituvchi'}</small></div></div></header>
      <div className="admin-content">
      {section==='users'&&user.role==='admin'?<UserAnalytics analytics={db.analytics}/>:section==='quizzes'?<>
        <div className="stats-grid"><Stat icon={<Gamepad2/>} label="Jami testlar" value={db.quizzes.length} color="purple"/><Stat icon={<Radio/>} label="Faol testlar" value={active} color="green"/><Stat icon={<Users/>} label="Ishtirokchilar" value={db.players.length} color="blue"/><Stat icon={<Activity/>} label="Javoblar" value={db.players.reduce((n,p)=>n+(p.answers||0),0)} color="orange"/></div>
        <section className="bank-banner"><div><span className="eyebrow"><Sparkles size={15}/> TAYYOR SAVOLLAR TO‘PLAMI</span><h2>Dars mavzusiga mos test tanlang</h2><p>{bank.length} yo‘nalish bo‘yicha {bank.reduce((sum,pack)=>sum+pack.questions.length,0)} ta tayyor savol</p></div><div className="bank-packs">{bank.map(pack=><button key={pack.id} className={pack.color} disabled={pending} onClick={()=>addPack(pack)}><Plus size={15}/>{pack.subject}</button>)}</div></section><div className="panel-card"><div className="panel-head"><div><h2>Barcha testlar</h2><p>Yangi test yarating yoki mavjud test holatini o‘zgartiring</p></div><button className="btn btn-primary" onClick={()=>setEditing('new')}><Plus/> Yangi test</button></div>
        <div className="table-wrap"><table><thead><tr><th>TEST NOMI</th><th>GURUH</th><th>SAVOLLAR</th><th>KOD</th><th>HOLAT</th><th></th></tr></thead><tbody>{db.quizzes.map(q=><tr key={q.id}><td><div className={`table-icon ${q.color}`}><Code2/></div><div><b>{q.title}</b><small>{q.subject}</small></div></td><td><span className="group-tag">{q.group}</span></td><td>{q.questions.length} ta</td><td><code>{q.pin}</code></td><td><button className={`status-switch ${q.status}`} onClick={()=>toggle(q.id)}><i/>{q.status==='active'?'OCHIQ':'YOPIQ'}</button></td><td><div className="row-actions"><button title="Tahrirlash" onClick={()=>setEditing(q.id)}><Pencil/></button><button className="danger" title="O‘chirish" onClick={()=>remove(q.id)}><Trash2/></button></div></td></tr>)}</tbody></table></div></div>
      </>:section==='national'?<NationalTestAdmin role={user.role} sections={db.nationalSections||[]} pending={pending} onCreate={()=>setNationalEditing('new')} onEdit={id=>setNationalEditing(id)} onReview={reviewNational} onDelete={removeNational}/>:section==='codes'?<PublicCodes quizzes={db.publicQuizzes||[]} notify={notify}/>:section==='lessons'?<LessonAdmin lessons={db.lessons||[]} pending={pending} onSave={saveLesson} onDelete={removeLesson}/>:section==='results'?<Leaderboard players={players} quizzes={db.quizzes} onReset={resetResults}/>:section==='race'?<RaceAdmin race={db.race} quizzes={db.quizzes} pending={pending} onActivate={activateRace} onStop={stopRace}/>:<TypingAdmin typing={db.typing} pending={pending} onStatus={setTypingStatus} onReset={resetTyping}/>} 
      </div>
    </div>
  </div>
}

function Stat({icon,label,value,color}){return <div className="stat-card"><span className={`stat-icon ${color}`}>{icon}</span><div><small>{label}</small><strong>{value}</strong></div></div>}

function UserAnalytics({analytics}){
 const [query,setQuery]=useState(''),[role,setRole]=useState('all'),now=Date.now(),users=analytics?.users||[];
 const visible=users.filter(user=>(role==='all'||user.role===role)&&(!query||`${user.name||''} ${user.email||''}`.toLowerCase().includes(query.toLowerCase())));
 const date=value=>value?new Date(value).toLocaleString('uz-UZ',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
 if(!analytics)return <section className="panel-card analytics-loading"><Activity/><h2>Statistika tayyorlanmoqda</h2><p>Foydalanuvchilar ma’lumoti bir necha soniyada ko‘rinadi.</p></section>;
 return <div className="user-analytics"><div className="stats-grid analytics-stats"><Stat icon={<Users/>} label="Jami foydalanuvchi" value={analytics.totalUsers} color="purple"/><Stat icon={<Radio/>} label="Hozir faol" value={analytics.activeUsers} color="green"/><Stat icon={<LogOut/>} label="Jami kirish" value={analytics.totalLogins} color="blue"/><Stat icon={<ArrowLeft/>} label="Jami chiqish" value={analytics.totalLogouts} color="orange"/></div><section className="panel-card analytics-summary"><div><b>{analytics.students}</b><span>O‘quvchi</span></div><div><b>{analytics.teachers}</b><span>O‘qituvchi</span></div><div><b>{users.filter(item=>item.role==='admin').length}</b><span>Administrator</span></div><div><b>{users.filter(item=>item.activity?.lastSeenAt&&now-item.activity.lastSeenAt<24*60*60*1000).length}</b><span>Bugun faol</span></div></section><section className="panel-card users-panel"><div className="panel-head"><div><h2>Foydalanuvchilar</h2><p>Oxirgi faollik va tizimga kirishlar bo‘yicha ro‘yxat</p></div><div className="user-filters"><label><Search/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Ism yoki email"/></label><select value={role} onChange={event=>setRole(event.target.value)}><option value="all">Barcha rollar</option><option value="student">O‘quvchilar</option><option value="teacher">O‘qituvchilar</option><option value="admin">Administratorlar</option></select></div></div><div className="table-wrap"><table className="users-table"><thead><tr><th>FOYDALANUVCHI</th><th>ROL</th><th>HOLAT</th><th>KIRISHLAR</th><th>CHIQISHLAR</th><th>OXIRGI FAOLLIK</th></tr></thead><tbody>{visible.map(user=>{const active=user.activity?.lastSeenAt&&now-user.activity.lastSeenAt<5*60*1000;return <tr key={user.uid||user.id}><td><span className="user-initial">{(user.name||'?').slice(0,1).toUpperCase()}</span><div><b>{user.name||'Nomsiz foydalanuvchi'}</b><small>{user.email||user.provider||'Email ko‘rsatilmagan'}</small></div></td><td><span className={`role-badge ${user.role}`}>{user.role==='admin'?'Administrator':user.role==='teacher'?'O‘qituvchi':'O‘quvchi'}</span></td><td><span className={`online-badge ${active?'online':'offline'}`}><i/>{active?'Faol':'Oflayn'}</span></td><td>{user.activity?.loginCount||0}</td><td>{user.activity?.logoutCount||0}</td><td>{date(user.activity?.lastSeenAt)}</td></tr>})}</tbody></table></div>{!visible.length&&<div className="empty-card compact"><Users/><h3>Foydalanuvchi topilmadi</h3><p>Qidiruv yoki rol filtrini o‘zgartirib ko‘ring.</p></div>}</section></div>
}

function NationalTestAdmin({role,sections,pending,onCreate,onEdit,onReview,onDelete}){
 const labels={draft:'Qoralama',pending:'Admin tasdig‘ida',approved:'Ommaviy',rejected:'Rad etilgan'},pendingCount=sections.filter(item=>item.approvalStatus==='pending').length;
 return <div className="national-admin"><section className="national-admin-hero panel-card"><div><span className="eyebrow"><GraduationCap/> MILLIY TESTLARGA TAYYORLOV</span><h2>Manbali milliy test variantlari</h2><p>Har bir variant 30 savoldan iborat. Bir nechta mavzuni qamrab oling va savol manbalarini kiriting.</p></div><button className="btn btn-primary" onClick={onCreate}><Plus/> Yangi 30 savollik bo‘lim</button></section><div className="stats-grid"><Stat icon={<BookOpen/>} label="Arxivdagi demo bo‘limlar" value={nationalSummary.sections} color="purple"/><Stat icon={<Code2/>} label="Arxivdagi demo savollar" value={nationalSummary.questions} color="blue"/><Stat icon={<Pencil/>} label="Siz yaratgan" value={sections.length} color="green"/><Stat icon={<Clock3/>} label="Tasdiq kutilmoqda" value={role==='admin'?pendingCount:sections.filter(item=>item.approvalStatus==='pending').length} color="orange"/></div><section className="panel-card national-builtins"><div className="panel-head"><div><h2>Eski demo arxivi — o‘quvchiga ko‘rsatilmaydi</h2><p>Bu savollar rasmiy manbalardan olinmagan va ommaviy katalogda yopilgan.</p></div></div><div className="national-mini-grid">{nationalTestBank.map(item=><article key={item.id}><span>{item.subject==='Matematika'?'∑':'EN'}</span><div><small>{item.subject} · 30 savol</small><b>{item.title}</b></div></article>)}</div></section><section className="panel-card"><div className="panel-head"><div><h2>{role==='admin'?'O‘qituvchilar yuborgan bo‘limlar':'Mening bo‘limlarim'}</h2><p>{role==='admin'?'Kutilayotgan bo‘limlarni tekshirib, ommaga chiqarishga ruxsat bering.':'Ommaga yuborilgan bo‘lim administrator tasdig‘idan o‘tadi.'}</p></div></div>{sections.length?<div className="national-admin-list">{sections.map(item=><article key={item.id}><div className="national-admin-subject">{item.subject==='Matematika'?'∑':'EN'}</div><div><small>{item.subject} · {item.ownerName}</small><h3>{item.title}</h3><p>{item.description||'Tavsif kiritilmagan'} · {item.questions?.length||30}/30 savol</p></div><span className={`approval-badge ${item.approvalStatus}`}>{labels[item.approvalStatus]||item.approvalStatus}</span><div className="national-admin-actions">{role==='admin'&&item.approvalStatus==='pending'&&<><button className="approve" disabled={pending} onClick={()=>onReview(item.id,'approved')}><Check/> Tasdiqlash</button><button disabled={pending} onClick={()=>onReview(item.id,'rejected')}><X/> Rad etish</button></>}<button title="Tahrirlash" onClick={()=>onEdit(item.id)}><Pencil/></button><button className="danger" title="O‘chirish" onClick={()=>onDelete(item.id)}><Trash2/></button></div></article>)}</div>:<div className="empty-card"><GraduationCap/><h3>Yangi bo‘lim yarating</h3><p>Bo‘limda aynan 30 ta, har birida 4 variantli savol bo‘lishi kerak.</p></div>}</section></div>
}

function NationalSectionEditor({section,role,saving,onCancel,onSave}){
 const blank=()=>({text:'',options:['','','',''],correct:0,explanation:'',topic:'',sourceUrl:'',sourceReference:''}),initialQuestions=section?.questions?.length===30?section.questions.map(item=>({...blank(),...item,options:[...item.options]})):Array.from({length:30},blank),[data,setData]=useState(section?{...section,questions:initialQuestions}:{title:'',subject:'Matematika',description:'',durationMinutes:60,questions:initialQuestions}),[index,setIndex]=useState(0),[requestPublic,setRequestPublic]=useState(section?.approvalStatus==='pending'||section?.approvalStatus==='approved');
 const current=data.questions[index],filled=data.questions.filter(item=>item.text.trim()&&item.options.every(option=>String(option).trim())).length,updateQuestion=patch=>setData(value=>({...value,questions:value.questions.map((item,qIndex)=>qIndex===index?{...item,...patch}:item)}));
 const submit=()=>{if(!data.title.trim())return alert('Bo‘lim nomini kiriting.');if(filled!==30)return alert(`Avval barcha 30 ta savolni to‘ldiring. Hozir ${filled} tasi tayyor.`);if(requestPublic){const issue=publicationError(data);if(issue)return alert(issue)}onSave({...data,requestPublic})};
 return <main className="national-editor-page"><header><button className="back-circle" onClick={onCancel}><ArrowLeft/></button><div><small>MILLIY TEST BO‘LIMI MUHARRIRI</small><h1>{section?'Bo‘limni tahrirlash':'30 savollik bo‘lim yaratish'}</h1></div><button className="btn btn-primary" disabled={saving||filled!==30} onClick={submit}><Save/> {saving?'Saqlanmoqda…':requestPublic?(role==='admin'?'Saqlash va e’lon qilish':'Admin tasdig‘iga yuborish'):'Qoralamani saqlash'}</button></header><div className="national-editor-layout"><aside><div><b>Savollar</b><span>{filled}/30 tayyor</span></div><div className="national-editor-map">{data.questions.map((item,qIndex)=><button className={`${item.text.trim()&&item.options.every(option=>String(option).trim())?'ready':''} ${qIndex===index?'current':''}`} onClick={()=>setIndex(qIndex)} key={qIndex}>{qIndex+1}</button>)}</div><small>Har savolda 4 ta variant va bitta to‘g‘ri javob bo‘lishi shart.</small></aside><div className="national-editor-main"><section className="panel-card form-card"><h2>Bo‘lim ma’lumotlari</h2><div className="form-grid"><label>Bo‘lim nomi<input value={data.title} onChange={e=>setData({...data,title:e.target.value})} placeholder="Masalan: Matematika — aralash 1-variant"/></label><label>Fan<select value={data.subject} onChange={e=>setData({...data,subject:e.target.value})}><option>Matematika</option><option>Ingliz tili</option></select></label><label>Vaqt (daqiqa)<input type="number" min="30" max="180" value={data.durationMinutes} onChange={e=>setData({...data,durationMinutes:Number(e.target.value)})}/></label></div><label>Qisqa tavsif<textarea value={data.description} maxLength={500} onChange={e=>setData({...data,description:e.target.value})} placeholder="Bu bo‘lim qaysi mavzu va ko‘nikmalarni tekshiradi?"/></label></section><section className="panel-card form-card national-question-editor"><div className="panel-head"><div><span className="eyebrow">{index+1}-SAVOL</span><h2>Savol va javob variantlari</h2></div><span>{filled}/30 tayyor</span></div><label>Savol matni<textarea value={current.text} onChange={e=>updateQuestion({text:e.target.value})} placeholder="Savolni to‘liq yozing..."/></label><div className="options-editor">{current.options.map((option,optionIndex)=><label className={current.correct===optionIndex?'correct-option':''} key={optionIndex}><button onClick={()=>updateQuestion({correct:optionIndex})}>{String.fromCharCode(65+optionIndex)}</button><input value={option} onChange={e=>{const options=[...current.options];options[optionIndex]=e.target.value;updateQuestion({options})}} placeholder={`${optionIndex+1}-variant`}/>{current.correct===optionIndex&&<Check/>}</label>)}</div><div className="form-grid"><label>Mavzu<input value={current.topic||''} maxLength={120} onChange={e=>updateQuestion({topic:e.target.value})} placeholder="Masalan: Trigonometriya"/></label><label>Asl manba (HTTPS)<input type="url" value={current.sourceUrl||''} maxLength={1000} onChange={e=>updateQuestion({sourceUrl:e.target.value})} placeholder="https://..."/></label><label>Manbadagi joyi<input value={current.sourceReference||''} maxLength={200} onChange={e=>updateQuestion({sourceReference:e.target.value})} placeholder="PDF 3-bet, 12-savol"/></label></div><label>Javob izohi<textarea value={current.explanation||''} onChange={e=>updateQuestion({explanation:e.target.value})} placeholder="Natijadan keyin ko‘rsatiladigan qisqa yechim yoki izoh"/></label><div className="national-editor-nav"><button className="btn btn-outline" disabled={index===0} onClick={()=>setIndex(index-1)}><ArrowLeft/> Oldingi</button><button className="btn btn-primary" disabled={index===29} onClick={()=>setIndex(index+1)}>Keyingi <ChevronRight/></button></div></section><label className="national-publish-choice"><input type="checkbox" checked={requestPublic} onChange={e=>setRequestPublic(e.target.checked)}/><span><b>{role==='admin'?'Ommaga e’lon qilish':'Administrator tasdig‘iga yuborish'}</b><small>{role==='admin'?'Saqlangach o‘quvchilarga darhol ko‘rinadi.':'Kamida 3 mavzu, har savolning manbasi va izohi kerak. Administrator tekshirgach e’lon qilinadi.'}</small></span></label></div></div></main>
}

function RaceAdmin({race,quizzes,pending,onActivate,onStop}){
 const active=race?.active,players=race?.racers||[];
 const eligible=quizzes.filter(quiz=>(quiz.questions||[]).filter(question=>question.type==='test'&&question.options?.length===4).length>=2);
 const [quizId,setQuizId]=useState(eligible[0]?.id||'');
 const selectedQuiz=eligible.find(quiz=>quiz.id===quizId)||eligible[0];
 const choices=(selectedQuiz?.questions||[]).filter(question=>question.type==='test'&&question.options?.length===4);
 const [selected,setSelected]=useState(()=>choices.slice(0,Math.min(10,choices.length)).map(question=>question.id));
 useEffect(()=>{const next=(eligible.find(quiz=>quiz.id===quizId)||eligible[0]);setSelected((next?.questions||[]).filter(question=>question.type==='test'&&question.options?.length===4).slice(0,10).map(question=>question.id))},[quizId]);
 const toggleQuestion=id=>setSelected(current=>current.includes(id)?current.filter(value=>value!==id):current.length<12?[...current,id]:current);
 const openRace=()=>onActivate({quizId:selectedQuiz?.id,questionIds:selected});
 const phases={lobby:'O‘quvchilar kutilmoqda',countdown:'Start sanog‘i',running:'Poyga davom etmoqda',finished:'Poyga yakunlandi',closed:'Yopilgan'};
 return <section className="race-admin panel-card"><div className="race-admin-hero"><div><span className="eyebrow"><Flag/> BITTA KOMPYUTERDA 1V1</span><h2>Savollarni o‘zingiz tanlang</h2><p>Avval 6 xonali kodga ega testingizni tanlang, keyin poygada ishlatiladigan savollarni belgilang. Ikki yo‘lakda savollar turli tartibda chiqadi.</p></div><button className="btn btn-primary" disabled={pending||selected.length<2} onClick={openRace}>{active?'Yangi poyga ochish':'Poygani ochish'} <Play/></button></div>
  <div className="race-question-picker"><label>Manba test<select value={selectedQuiz?.id||''} onChange={event=>setQuizId(event.target.value)}>{eligible.map(quiz=><option key={quiz.id} value={quiz.id}>{quiz.pin} · {quiz.title}</option>)}</select></label><div className="race-picker-head"><b>{selectedQuiz?`${selectedQuiz.pin} kodli test savollari`:'Mos test topilmadi'}</b><span>{selected.length}/12 tanlandi</span></div>{choices.length?<div className="race-picker-list">{choices.map((question,index)=><label className={selected.includes(question.id)?'chosen':''} key={question.id}><input type="checkbox" checked={selected.includes(question.id)} disabled={!selected.includes(question.id)&&selected.length>=12} onChange={()=>toggleQuestion(question.id)}/><span>{index+1}</span><b>{question.text}</b></label>)}</div>:<p className="picker-empty">Poyga uchun kamida 2 ta to‘rt variantli savolga ega test yarating.</p>}</div>
  {active?<><div className="race-admin-status"><span className={`live-dot ${race.phase}`}/><div><b>{phases[race.phase]||race.phase}</b><small>{players.length}/2 o‘quvchi · {race.questionCount} savol</small></div><button className="btn btn-outline" disabled={pending} onClick={onStop}>Poygani yopish</button></div><div className="race-admin-racers">{[0,1].map(index=>{const player=players[index];return <article key={index}><span>{player?.avatar||'🏁'}</span><div><b>{player?.name||`${index+1}-o‘quvchi kutilmoqda`}</b><small>{player?`${player.index}/${race.questionCount} · ${player.ready?'Tayyor':'Tayyor emas'}`:'Bosh sahifa orqali kiradi'}</small></div><strong>{player?.index||0}<small>/{race.questionCount}</small></strong></article>})}</div>{race.phase==='finished'&&<div className="race-admin-winner"><Trophy/><b>{players.find(player=>player.id===race.winnerId)?.name} g‘olib!</b></div>}</>:<div className="empty-card compact"><Flag/><h3>Poyga hozir yopiq</h3><p>Test va savollarni tanlab, “Poygani ochish” tugmasini bosing.</p></div>}
 </section>
}

function TypingAdmin({typing,pending,onStatus,onReset}){
 const active=!!typing?.active,results=typing?.results||[];
 return <section className="typing-admin panel-card">
  <div className="typing-admin-hero"><div><span className="eyebrow"><Headphones/> INGLIZ TILI VA MATN TERISH</span><h2>Ikki yo‘nalishdagi amaliy mashqlar</h2><p>O‘quvchi ingliz tili darajasini aniqlashi, gaplarni tinglab yozishi yoki bosqichma-bosqich uzun matn terishi mumkin.</p></div><button className={`status-switch large ${active?'active':'passive'}`} disabled={pending} onClick={()=>onStatus(!active)}><i/>{active?'OCHIQ':'YOPIQ'}</button></div>
  <div className="typing-levels">{Object.entries(englishLevels).map(([code,label])=><div key={code}><b>{code}</b><span>{label}</span></div>)}</div>
  <div className="typing-admin-status"><div><span className={`live-dot ${active?'running':''}`}/><b>{active?'O‘quvchilar uchun ochiq':'Hozir yopiq'}</b><small>{active?'Mashq bosh sahifada ko‘rinib turibdi.':'Ochish tugmasini bossangiz, mashq o‘quvchilarga ko‘rinadi.'}</small></div><div><strong>{typing?.studentCount||0}</strong><small>Mashq qilmoqda</small></div><div><strong>{results.length}</strong><small>Yakunlagan</small></div></div>
  <div className="panel-head typing-results-head"><div><h2>Matn terish natijalari</h2><p>Mashqni to‘liq yakunlagan o‘quvchilar</p></div>{results.length>0&&<button className="btn btn-outline" disabled={pending} onClick={onReset}><Trash2/> Tozalash</button>}</div>
  {results.length?<div className="table-wrap"><table><thead><tr><th>O‘QUVCHI</th><th>YO‘NALISH</th><th>DARAJA</th><th>TEZLIK</th><th>ANIQLIK</th><th>VAQT</th></tr></thead><tbody>{results.map(item=><tr key={item.id+item.completedAt}><td><span className="typing-result-avatar">{item.avatar}</span><b>{item.name}</b></td><td>{item.courseMode==='longtext'?'Uzun matn':'Ingliz tili'}</td><td><strong>{item.courseMode==='longtext'?'5 bosqich':item.englishLevel||'A1'}</strong></td><td><strong>{item.averageWpm} WPM</strong></td><td>{item.averageAccuracy}%</td><td>{Math.floor(item.totalSeconds/60)} min {Math.round(item.totalSeconds%60)} s</td></tr>)}</tbody></table></div>:<div className="empty-card compact"><Headphones/><h3>Natijalar hali mavjud emas</h3><p>O‘quvchi mashqni tugatgach, uning natijasi shu yerda ko‘rinadi.</p></div>}
 </section>
}

function PublicCodes({quizzes,notify}){
 const copy=async pin=>{try{await navigator.clipboard.writeText(pin);notify('Kod nusxalandi.')}catch{notify(`Test kodi: ${pin}`)}};
 return <section className="panel-card public-codes"><div className="panel-head"><div><h2>O‘qituvchilar ulashgan testlar</h2><p>Ommaviy qilingan faol testlar va ularning kirish kodlari</p></div></div>{quizzes.length?<div className="codes-grid">{quizzes.filter(quiz=>quiz.status==='active').map(quiz=><article key={quiz.id}><div><span className="table-icon violet"><Code2/></span><div><small>{quiz.subject} · {quiz.group}</small><h3>{quiz.title}</h3></div></div><p>{quiz.questions?.length||quiz.questionCount||0} ta savol · {quiz.ownerName||'O‘qituvchi'}</p><footer><code>{quiz.pin}</code><button onClick={()=>copy(quiz.pin)}><Copy/> Kodni olish</button></footer></article>)}</div>:<div className="empty-card"><Code2/><h3>Ommaviy testlar hali yo‘q</h3><p>O‘qituvchi testni “Ommaviy” qilib ochganda uning kodi shu yerda ko‘rinadi.</p></div>}</section>
}

function LessonAdmin({lessons,pending,onSave,onDelete}){
 const empty={title:'',subject:'Matematika',summary:'',content:'',cover:'📘',visibility:'public'};const [form,setForm]=useState(null);
 const submit=async()=>{if(!form?.title.trim()||!form?.content.trim())return;const result=await onSave(form);if(result)setForm(null)};
 if(form)return <section className="lesson-editor panel-card"><div className="panel-head"><div><h2>{form.id?'Darslikni tahrirlash':'Yangi darslik yozish'}</h2><p>Matnni mavzular bo‘yicha xatboshilarga ajratib yozing</p></div><button className="btn btn-ghost" onClick={()=>setForm(null)}><X/> Bekor qilish</button></div><div className="lesson-form-grid"><label>Sarlavha<input value={form.title} onChange={e=>setForm({...form,title:e.target.value})} placeholder="Masalan: Tenglamalarni yechish usullari"/></label><label>Fan yoki bo‘lim<input value={form.subject} onChange={e=>setForm({...form,subject:e.target.value})} placeholder="Matematika"/></label><label>Muqova belgisi<input value={form.cover} maxLength={4} onChange={e=>setForm({...form,cover:e.target.value})}/></label><label>Ko‘rinishi<select value={form.visibility} onChange={e=>setForm({...form,visibility:e.target.value})}><option value="public">Barcha o‘quvchilar uchun</option><option value="private">Faqat o‘qituvchi uchun qoralama</option></select></label></div><label>Qisqa tavsif<textarea value={form.summary} maxLength={280} onChange={e=>setForm({...form,summary:e.target.value})} placeholder="O‘quvchi bu darsda nimalarni o‘rganadi?"/></label><label>Dars matni<textarea className="lesson-content-input" value={form.content} onChange={e=>setForm({...form,content:e.target.value})} placeholder={'Kirish\n\nAsosiy tushunchalar...\n\nAmaliy topshiriq...'}/></label><button className="btn btn-primary" disabled={pending||!form.title.trim()||!form.content.trim()} onClick={submit}><Save/> {pending?'Saqlanmoqda…':'Darslikni saqlash'}</button></section>;
 return <section className="panel-card lesson-admin"><div className="panel-head"><div><h2>Mening darsliklarim</h2><p>O‘quvchilar uchun mavzuli qo‘llanma va dars matnlarini e’lon qiling</p></div><button className="btn btn-primary" onClick={()=>setForm({...empty})}><Plus/> Yangi darslik</button></div>{lessons.length?<div className="lesson-admin-list">{lessons.map(lesson=><article key={lesson.id}><span>{lesson.cover||'📘'}</span><div><small>{lesson.subject} · {lesson.visibility==='public'?'E’lon qilingan':'Qoralama'}</small><h3>{lesson.title}</h3><p>{lesson.summary||lesson.content.slice(0,110)+'…'}</p></div><div><button title="Tahrirlash" onClick={()=>setForm({...lesson})}><Pencil/></button><button className="danger" title="O‘chirish" onClick={()=>onDelete(lesson.id)}><Trash2/></button></div></article>)}</div>:<div className="empty-card"><BookOpen/><h3>Birinchi darsligingizni yozing</h3><p>Mavzu, qisqa izoh va dars matnini kiriting. E’lon qilingan darsliklar o‘quvchilar kabinetida ko‘rinadi.</p></div>}</section>
}

function Leaderboard({players:allPlayers,quizzes,onReset}){
  const [filter,setFilter]=useState('');
  const players=allPlayers.filter(p=>!filter||p.quizId===filter);
  return <div className="panel-card"><div className="panel-head"><div><div className="eyebrow"><span className="live-dot"/> JONLI NATIJALAR</div><h2>O‘quvchilar reytingi</h2><p>Natijalar har bir javobdan so‘ng yangilanadi</p></div><button className="btn btn-outline" onClick={onReset}><Trash2/> Tozalash</button></div>
    <div className="rank-filter"><select aria-label="Reyting testini tanlang" value={filter} onChange={e=>setFilter(e.target.value)}><option value="">Barcha testlar</option>{quizzes.map(q=><option value={q.id} key={q.id}>{q.title} · {q.group}</option>)}</select></div>{players.length?<div className="leader-list">{players.map((p,i)=><div className={`leader-row ${i<3?'top-'+(i+1):''}`} key={p.id}><div className="place">{i===0?'🥇':i===1?'🥈':i===2?'🥉':i+1}</div><div className="leader-avatar"><Avatar3D value={p.avatar}/></div><div className="leader-name"><b>{p.name}</b><small>{quizzes.find(q=>q.id===p.quizId)?.title||'Test'}</small></div><div className="progress"><i style={{width:`${Math.min(100,p.score/8)}%`}}/></div><strong>{p.score} <small>ball</small></strong></div>)}</div>:<div className="empty-card compact"><Trophy/><h3>Hali natijalar yo‘q</h3><p>O‘quvchilar test boshlaganda shu yerda ko‘rinadi.</p></div>}
    {players.some(p=>p.responses?.length)&&<details className="answer-review"><summary>Yozma javoblar va baholash tafsilotlari</summary>{players.map(p=><div key={p.id}>{p.responses?.filter(r=>r.type!=='test').map((r,i)=><article key={i}><b>{p.name} · {r.earned} ball</b><p>{r.text}</p><pre>{r.value||'Javob berilmagan'}</pre>{r.checks?.map((c,j)=><span key={j}>{c.passed?'✓':'○'} {c.label} · </span>)}</article>)}</div>)}</details>}
  </div>
}

function QuizEditor({quiz,onCancel,onSave,saving=false}){
  const [data,setData]=useState(quiz||{id:uid(),title:'',group:'',subject:'Matematika',status:'passive',visibility:'private',pin:String(Math.floor(100000+Math.random()*900000)),color:'violet',questions:[],createdAt:Date.now()});
  const blank=()=>({type:'test',text:'',options:['','','',''],correct:0,answer:'',points:100,time:30,subject:'Matematika',criteria:[],acceptedAnswers:[],explanation:''});
  const [form,setForm]=useState(blank);
  const [editingQ,setEditingQ]=useState(null);
  const saveQuestion=()=>{if(!form.text.trim())return alert('Savol matnini kiriting'); if(form.type==='test'&&form.options.some(x=>!x.trim()))return alert('4 ta variantni ham kiriting'); if(form.type!=='test'&&!form.answer.trim())return alert('Namuna javobni kiriting');if(form.type==='prompt'&&(!form.criteria?.length||form.criteria.some(c=>!c.label.trim()||!c.keywords.some(k=>k.trim()))))return alert('Prompt uchun kamida bitta nomlangan kalit so‘z mezoni kiriting');if(Number(form.time)<10||Number(form.time)>3600||Number(form.points)<10||Number(form.points)>10000)return alert('Vaqt 10–3600 sekund, ball 10–10000 oralig‘ida bo‘lsin');const q={...form,id:editingQ||uid(),points:Number(form.points),time:Number(form.time)}; setData(d=>({...d,questions:editingQ?d.questions.map(x=>x.id===editingQ?q:x):[...d.questions,q]}));cancelQuestion()};
  const cancelQuestion=()=>{setForm(blank());setEditingQ(null)};
  const editQ=q=>{setForm({...blank(),...q,options:q.options||['','','',''],answer:q.answer||''});setEditingQ(q.id);window.scrollTo({top:0,behavior:'smooth'})};
  const submit=()=>{if(!data.title.trim()||!data.group.trim())return alert('Test nomi va guruhni kiriting');if(!/^\d{6}$/.test(data.pin))return alert('Kod 6 ta raqamdan iborat bo‘lsin');if(!data.questions.length)return alert('Kamida 1 ta savol qo‘shing');onSave(data)};
  return <div className="editor-page"><header><button className="back-circle" onClick={onCancel}><ArrowLeft/></button><div><small>TEST MUHARRIRI</small><h1>{quiz?'Testni tahrirlash':'Yangi test yaratish'}</h1></div><button className="btn btn-primary" disabled={saving} onClick={submit}><Save/> {saving?'Saqlanmoqda…':'Saqlash'}</button></header><div className="editor-layout"><div className="editor-main">
    <section className="panel-card form-card"><h2>Asosiy ma’lumotlar</h2><div className="form-grid"><label>Test nomi<input value={data.title} onChange={e=>setData({...data,title:e.target.value})} placeholder="Masalan: Word va Excel"/></label><label>Guruh<input value={data.group} onChange={e=>setData({...data,group:e.target.value})} placeholder="Masalan: 8-A"/></label><label>Fan<input value={data.subject} onChange={e=>setData({...data,subject:e.target.value})}/></label><label>O‘yin kodi<input value={data.pin} onChange={e=>setData({...data,pin:e.target.value.replace(/\D/g,'').slice(0,6)})}/></label><label>Kimlar ko‘ra oladi?<select value={data.visibility||'private'} onChange={e=>setData({...data,visibility:e.target.value})}><option value="private">Faqat kod berilgan o‘quvchilar</option><option value="public">Ommaviy — barcha foydalanuvchilar</option></select></label></div><p className="visibility-help">Ommaviy testning mavzusi va kodi boshqa o‘qituvchilarning “Ommaviy kodlar” bo‘limida ham ko‘rinadi.</p></section>
    <section className="panel-card form-card"><div className="panel-head"><div><h2>{editingQ?'Savolni tahrirlash':'Yangi savol'}</h2><p>Istalgan fan uchun test yoki amaliy topshiriq</p></div><div className="type-tabs">{Object.entries(questionTypes).map(([type,label])=><button key={type} className={form.type===type?'on':''} onClick={()=>setForm({...form,type})}>{label}</button>)}</div></div><label>Mavzu<select value={form.subject} onChange={e=>setForm({...form,subject:e.target.value})}>{['Matematika','Ingliz tili','Ona tili','Tarix','Biologiya','Geografiya','Fizika','Kimyo','Informatika','Word','Excel','PowerPoint','Keyboard shortcuts','Prompt engineering'].map(t=><option key={t}>{t}</option>)}</select></label><label>Savol matni<textarea value={form.text} onChange={e=>setForm({...form,text:e.target.value})} placeholder="Savol yoki topshiriqni yozing..."/></label>
      {form.type==='test'?<div className="options-editor">{form.options.map((op,i)=><label className={form.correct===i?'correct-option':''} key={i}><button onClick={()=>setForm({...form,correct:i})}>{String.fromCharCode(65+i)}</button><input value={op} onChange={e=>{const a=[...form.options];a[i]=e.target.value;setForm({...form,options:a})}} placeholder={`${i+1}-variant`}/>{form.correct===i&&<Check/>}</label>)}</div>:<label>Namuna to‘g‘ri javob<textarea className="code-input" value={form.answer} onChange={e=>setForm({...form,answer:e.target.value})} placeholder={form.type==='shortcut'?'Masalan: Ctrl+B':'Namuna javob, formula yoki prompt...'}/></label>}
      {form.type==='prompt'&&<div className="rubric-editor"><h3>Baholash mezonlari</h3><p>Javobda belgilangan kalit so‘zlardan biri uchrasa, tegishli mezon uchun ball beriladi. Yakuniy mazmunni o‘qituvchi ko‘rib chiqadi.</p>{form.criteria.map((c,i)=><div className="criterion-edit" key={i}><label>Mezon nomi<input value={c.label} onChange={e=>setForm({...form,criteria:form.criteria.map((x,j)=>j===i?{...x,label:e.target.value}:x)})}/></label><label>Kalit so‘zlar (; bilan ajrating)<input value={c.keywords.join(';')} onChange={e=>setForm({...form,criteria:form.criteria.map((x,j)=>j===i?{...x,keywords:e.target.value.split(';')}:x)})}/></label><button className="btn btn-ghost" aria-label="Mezonni o‘chirish" onClick={()=>setForm({...form,criteria:form.criteria.filter((_,j)=>j!==i)})}><Trash2 size={16}/></button></div>)}<button className="btn btn-outline" onClick={()=>setForm({...form,criteria:[...form.criteria,{label:'',keywords:[]}]})}><Plus size={16}/> Mezon qo‘shish</button></div>}
      {form.type==='practical'&&<label>Boshqa qabul qilinadigan javoblar (har qatorga bittadan)<textarea value={form.acceptedAnswers.join('\n')} onChange={e=>setForm({...form,acceptedAnswers:e.target.value.split('\n').filter(Boolean)})}/></label>}
      <label>Javobdan keyingi tushuntirish<textarea value={form.explanation} onChange={e=>setForm({...form,explanation:e.target.value})} placeholder="Ixtiyoriy izoh..."/></label>
      <div className="question-meta"><label>Ball<input type="number" min="10" value={form.points} onChange={e=>setForm({...form,points:e.target.value})}/></label><label>Vaqt (sekund)<input type="number" min="10" value={form.time} onChange={e=>setForm({...form,time:e.target.value})}/></label><button className="btn btn-primary" onClick={saveQuestion}>{editingQ?<Save/>:<Plus/>}{editingQ?'Yangilash':'Savol qo‘shish'}</button>{editingQ&&<button className="btn btn-ghost" onClick={cancelQuestion}>Bekor qilish</button>}</div>
    </section></div>
    <aside className="questions-side"><div className="side-title"><div><h3>Savollar</h3><p>{data.questions.length} ta savol</p></div></div>{data.questions.map((q,i)=><div className="question-item" key={q.id}><span>{i+1}</span><div><b>{q.text}</b><small>{questionTypes[q.type]} · {q.points} ball</small></div><button onClick={()=>editQ(q)}><Pencil/></button><button className="danger" onClick={()=>setData({...data,questions:data.questions.filter(x=>x.id!==q.id)})}><Trash2/></button></div>)}{!data.questions.length&&<div className="side-empty">Savollar hali qo‘shilmagan</div>}</aside>
  </div></div>
}

function Join({quiz,onBack,onStart}){
  const [name,setName]=useState('');const [avatar,setAvatar]=useState(avatars[0]);const [busy,setBusy]=useState(false);const [error,setError]=useState('');
  const start=async()=>{if(busy)return;setBusy(true);setError('');try{await onStart({name:name.trim(),avatar})}catch(e){setError(e.message)}finally{setBusy(false)}};
  if(!quiz)return null;
  return <div className="join-page"><div className="join-top"><button onClick={onBack}><ArrowLeft/></button><Brand light/><span/></div><div className="join-card"><div className="join-quiz"><span><Code2/></span><div><small>{quiz.subject} · {quiz.group}</small><h2>{quiz.title}</h2><p>{quiz.questionCount} ta savol va amaliy topshiriq</p><div className="no-account-badge"><Check size={15}/> Kod qabul qilindi</div></div></div><div className="join-form"><span className="join-step">KOD TASDIQLANDI</span><h1>Testga tayyorlaning</h1><p>Natijalar ro‘yxatida ko‘rinishi uchun ismingizni yozing va o‘zingizga yoqqan avatarni tanlang.</p><label>Ismingiz<input value={name} onChange={e=>setName(e.target.value.slice(0,30))} placeholder="Ismingizni kiriting" autoFocus/></label><label>Avatarni tanlang</label><div className="avatar-grid">{avatars.map((a,i)=><button aria-label={`Avatar ${i+1}`} aria-pressed={avatar===a} key={a} className={avatar===a?'chosen':''} onClick={()=>setAvatar(a)}><Avatar3D value={a} index={i}/>{avatar===a&&<i><Check/></i>}</button>)}</div><button className="btn btn-primary wide join-button" disabled={!name.trim()||busy} onClick={start}>{busy?'Ulanmoqda…':'Testni boshlash'} <Play size={19} fill="currentColor"/></button>{error&&<p className="form-error" role="alert">{error}</p>}</div></div></div>
}

function TypingJoin({onBack,onStart}){
 const [name,setName]=useState('');const [avatar,setAvatar]=useState(avatars[0]);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [courseMode,setCourseMode]=useState('english');const [entryMode,setEntryMode]=useState('placement');const [englishLevel,setEnglishLevel]=useState('A1');const [adaptive,setAdaptive]=useState(newPlacementTest);const [testDone,setTestDone]=useState(false);const [placementScore,setPlacementScore]=useState(null);
 const profileReady=courseMode==='longtext'||entryMode==='selected'||testDone;
 const resetPlacement=()=>{setAdaptive(newPlacementTest());setTestDone(false);setPlacementScore(null);setEnglishLevel('A1');setError('')};
 const answerPlacement=optionIndex=>{const correct=optionIndex===adaptive.question.answer,currentIndex=placementLevels.indexOf(adaptive.level),nextIndex=Math.max(0,Math.min(placementLevels.length-1,currentIndex+(correct?1:-1))),nextLevel=placementLevels[nextIndex],record={id:adaptive.question.id,level:adaptive.level,kind:adaptive.question.kind,correct},history=[...adaptive.history,record],used=[...adaptive.used,adaptive.question.id];if(history.length===15){setPlacementScore(history.filter(item=>item.correct).length);setEnglishLevel(nextLevel);setTestDone(true);setAdaptive({...adaptive,history,used,step:15,level:nextLevel});return}const nextKind=[2,5,8,11,14].includes(history.length)?'reading':'language';setAdaptive({step:history.length,level:nextLevel,question:randomPlacementQuestion(nextLevel,used,nextKind),history,used})};
 const start=async()=>{if(busy||!name.trim()||!profileReady)return;setBusy(true);setError('');try{await onStart({name:name.trim(),avatar,courseMode,englishLevel,entryMode:courseMode==='longtext'?'longtext':entryMode,placementScore})}catch(e){setError(e.message)}finally{setBusy(false)}};
 return <div className="join-page typing-join-page"><div className="join-top"><button onClick={onBack}><ArrowLeft/></button><Brand light/><span/></div><div className="join-card typing-join-card"><div className="join-quiz typing-join-banner"><span>{courseMode==='english'?<Headphones/>:<Keyboard/>}</span><div><small>IKKI YO‘NALISHDAGI MASHQ</small><h2>{courseMode==='english'?'Inglizcha tinglab yozish':'Uzun matn terish'}</h2><p>{courseMode==='english'?'Gapni tinglang, tushuning va to‘liq yozing':'Qisqa gaplardan boshlab katta matnlargacha mashq qiling'}</p><div className="no-account-badge"><Check size={15}/> Natija o‘qituvchiga saqlanadi</div></div></div><div className="join-form typing-join-form"><span className="join-step">1-QADAM · MASHQ YO‘NALISHI</span><h1>Mashq turini tanlang</h1><p>Inglizcha gaplarni tinglab yozing yoki tez va aniq matn terishni mashq qiling.</p>
   <div className="course-mode-grid"><button className={courseMode==='english'?'active':''} onClick={()=>setCourseMode('english')}><Headphones/><b>Ingliz tili</b><small>Daraja testi, talaffuz, tarjima va yangi so‘zlar</small></button><button className={courseMode==='longtext'?'active':''} onClick={()=>setCourseMode('longtext')}><Keyboard/><b>Uzun matn</b><small>5 bosqichli tez va aniq yozish mashqi</small></button></div>
   {courseMode==='english'&&<><div className="typing-profile-separator"><span>2-QADAM · INGLIZ TILI DARAJASI</span></div><div className="typing-choice-tabs"><button className={entryMode==='placement'?'active':''} onClick={()=>{setEntryMode('placement');resetPlacement()}}><GraduationCap/> Darajani aniqlash <small>Tavsiya etiladi</small></button><button className={entryMode==='selected'?'active':''} onClick={()=>{setEntryMode('selected');setTestDone(false);setError('')}}><BookOpen/> Darajani o‘zim tanlayman</button></div>
   {entryMode==='placement'&&!testDone&&<section className="adaptive-placement"><div className="placement-head"><b>Ingliz tili darajasini aniqlash</b><span>{adaptive.step+1} / 15</span></div><div className="placement-progress" aria-label={`Test ${Math.round(adaptive.step/15*100)} foiz bajarildi`}><i style={{width:`${adaptive.step/15*100}%`}}/></div><div className="adaptive-level-path">{placementLevels.map(level=><span className={level===adaptive.level?'current':''} key={level}>{level}</span>)}</div><small>10 ta grammatika va lug‘at savoli · 5 ta darajaga mos reading savoli</small>{adaptive.question.kind==='reading'&&<div className="placement-reading"><span><BookOpen/> READING · {adaptive.level}</span><p>{adaptive.question.passage}</p></div>}<h2>{adaptive.question.text}</h2><div className="adaptive-options">{adaptive.question.options.map((option,index)=><button onClick={()=>answerPlacement(index)} key={option}><span>{String.fromCharCode(65+index)}</span>{option}</button>)}</div></section>}
   {entryMode==='placement'&&testDone&&<section className="placement-result"><Award/><div><small>TAVSIYA ETILGAN DARAJA</small><h2>{englishLevel} · {englishLevels[englishLevel]}</h2><p>15 ta savoldan {placementScore} tasiga to‘g‘ri javob berdingiz. Mashqlar shu darajadan boshlanadi.</p></div><button className="btn btn-outline" onClick={resetPlacement}>Qayta topshirish</button></section>}
   {entryMode==='selected'&&<div className="english-level-grid">{Object.entries(englishLevels).map(([code,label])=><button className={englishLevel===code?'chosen':''} aria-pressed={englishLevel===code} onClick={()=>setEnglishLevel(code)} key={code}><b>{code}</b><span>{label}</span><small>{code==='A1'?'Oddiy kundalik gaplar':code==='A2'?'Maktab va odatiy mavzular':code==='B1'?'Bog‘langan, o‘rta gaplar':code==='B2'?'Murakkab va akademik gaplar':code==='C1'?'Ilg‘or tahlil va aniq ifoda':'Nozik ma’no va mukammal tuzilma'}</small>{englishLevel===code&&<Check/>}</button>)}</div>}</>}
   {profileReady&&<><div className="typing-profile-separator"><span>{courseMode==='english'?'3':'2'}-QADAM · O‘QUVCHI MA’LUMOTI</span></div><label>Ismingiz<input value={name} onChange={e=>setName(e.target.value.slice(0,30))} placeholder="Ismingizni kiriting" autoFocus/></label><label>Avatarni tanlang</label><div className="avatar-grid">{avatars.map((avatarValue,index)=><button aria-label={`Avatar ${index+1}`} aria-pressed={avatar===avatarValue} key={avatarValue} className={avatar===avatarValue?'chosen':''} onClick={()=>setAvatar(avatarValue)}><Avatar3D value={avatarValue} index={index}/>{avatar===avatarValue&&<i><Check/></i>}</button>)}</div><button className="btn btn-primary wide join-button" disabled={!name.trim()||busy} onClick={start}>{busy?'Ulanmoqda…':courseMode==='longtext'?'Mashqni boshlash':`${englishLevel} darajasini boshlash`} {courseMode==='longtext'?<Keyboard size={19}/>:<Headphones size={19}/>}</button></>}{error&&<p className="form-error" role="alert">{error}</p>}</div></div></div>
}

function TypingScreen({game,onUpdate,onLeave}){
 const {stage,stageStartedAt,feedback,finished}=game;const [typed,setTyped]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [pasteBlocked,setPasteBlocked]=useState(false);const [now,setNow]=useState(Date.now());const inflight=useRef(false);const inputRef=useRef(null);const total=game.stageCount||5,isEnglish=game.courseMode!=='longtext';
 useEffect(()=>{setTyped('');setError('');setPasteBlocked(false)},[stage?.id]);
 useEffect(()=>{if(!stageStartedAt)return;const timer=setInterval(()=>setNow(Date.now()),250);return()=>clearInterval(timer)},[stageStartedAt]);
 useEffect(()=>{if(stageStartedAt&&!feedback)inputRef.current?.focus()},[stageStartedAt,feedback,stage?.id]);
 useEffect(()=>()=>{if(typeof window!=='undefined')window.speechSynthesis?.cancel()},[]);
 const target=stage?.text||'',elapsed=Math.max(1,(now-(stageStartedAt||now))/1000),targetChars=[...target],typedChars=[...typed],errors=typedChars.reduce((count,char,index)=>count+Number(char!==targetChars[index]),0),accuracy=typedChars.length?Math.max(0,Math.round((1-errors/typedChars.length)*100)):100,wpm=stageStartedAt?Math.max(0,Math.round(((typedChars.length-errors)/5)/(elapsed/60))):0,progress=target.length?Math.min(100,Math.round(typed.length/target.length*100)):0;
 const action=async(path,data)=>{if(inflight.current)return;inflight.current=true;setBusy(true);setError('');try{const next=await api(path,{method:'POST',role:'typing',data});if(path.endsWith('/submit'))playSound(next.feedback?.passed?'correct':'wrong');onUpdate(next)}catch(e){setError(e.message)}finally{inflight.current=false;setBusy(false)}};
 const listen=rate=>{if(!speakEnglish(stage?.text,rate))setError('Bu brauzer ovozli o‘qishni qo‘llamaydi. Chrome yoki Edge’da ochib ko‘ring.')};
 const begin=()=>{setTyped('');setNow(Date.now());if(isEnglish)speakEnglish(stage?.text,.86);action('/api/typing/start')};
 if(finished){const averageAccuracy=Math.round(game.results.reduce((sum,item)=>sum+item.accuracy,0)/Math.max(1,game.results.length)*10)/10,averageWpm=Math.round(game.results.reduce((sum,item)=>sum+item.wpm,0)/Math.max(1,game.results.length));return <main className="typing-page"><section className="typing-finish"><Celebration/><div className="typing-finish-icon"><Trophy/></div><span>{isEnglish?game.englishLevel:'UZUN MATN'} · {total} BOSQICH YAKUNLANDI</span><h1>Barakalla, {game.name}!</h1><p>{isEnglish?'Inglizcha gaplarni tinglash va to‘g‘ri yozish mashqlarini muvaffaqiyatli yakunladingiz.':'Barcha matn terish bosqichlarini muvaffaqiyatli yakunladingiz.'}</p><div className="typing-finish-stats"><div><strong>{averageWpm}</strong><small>O‘rtacha tezlik</small></div><div><strong>{averageAccuracy}%</strong><small>O‘rtacha aniqlik</small></div><div><strong>{isEnglish?game.englishLevel:`${total}/${total}`}</strong><small>{isEnglish?'Ingliz tili darajasi':'Bosqichlar'}</small></div></div><button className="btn btn-primary" onClick={onLeave}><Home/> Bosh sahifaga qaytish</button></section></main>}
 return <main className="typing-page"><header className="typing-header"><div><span>{isEnglish?<Headphones/>:<Keyboard/>} {isEnglish?`TINGLAB YOZISH · ${game.englishLevel}`:'UZUN MATN · 5 BOSQICH'}</span><h1>{stage.title}</h1><p>{game.name} · {stage.description} · {stage.wordCount} so‘z</p></div><button className="btn btn-outline" onClick={()=>{if(confirm('Mashqdan chiqishni xohlaysizmi?'))onLeave()}}><ArrowLeft/> Chiqish</button></header>
  <nav className="typing-steps" aria-label="Typing bosqichlari">{Array.from({length:total},(_,index)=>index+1).map(level=><div className={level<stage.level?'done':level===stage.level?'current':''} key={level}><span>{level<stage.level?<Check/>:level}</span><b>{level}-bosqich</b></div>)}</nav>
  {!stageStartedAt&&feedback&&<section className={`typing-stage-result ${feedback.passed?'passed':'retry'}`}><span>{feedback.passed?<Check/>:<X/>}</span><div><small>{feedback.passed?'BOSQICH YAKUNLANDI':'QAYTA URINIB KO‘RING'}</small><h2>{feedback.passed?`${feedback.stage}-bosqich bajarildi`:isEnglish?'Gapni yana bir bor tinglang':'Matnni aniqroq tering'}</h2><p className="typing-correct-answer"><b>{isEnglish?feedback.correctText:'Keyingi bosqichga o‘tish uchun matnni kamida 90% aniqlikda tering.'}</b>{isEnglish&&<small>{feedback.translation}</small>}</p></div><div className="typing-result-numbers"><b>{feedback.wpm}<small>WPM</small></b><b>{feedback.accuracy}%<small>Aniqlik</small></b><b>{feedback.errors}<small>Xato</small></b></div><button className="btn btn-primary" disabled={busy} onClick={begin}>{feedback.passed?'Davom etish':'Qayta urinish'} <ChevronRight/></button></section>}
  {!stageStartedAt&&!feedback&&<section className="typing-ready">{isEnglish?<Headphones/>:<Keyboard/>}<span>{isEnglish?game.englishLevel:'UZUN MATN'} · {stage.level}-BOSQICH</span><h2>{stage.title}</h2><p>{isEnglish?'Gapni tinglang, undagi yetishmayotgan so‘zni aniqlang va gapni to‘liq yozing.':'Matn bilan tanishib chiqing. Boshlash tugmasini bosganingizdan keyin vaqt hisoblanadi.'}</p><div><b>{stage.wordCount}<small>so‘z</small></b><b>90%<small>minimal aniqlik</small></b></div><button className="btn btn-primary" disabled={busy} onClick={begin}>{isEnglish?<><Volume2/> Gapni tinglash</>:<><Play/> Mashqni boshlash</>}</button></section>}
  {stageStartedAt&&!feedback&&<section className="typing-workspace"><div className="typing-live-stats"><div><strong>{wpm}</strong><small>WPM</small></div><div><strong>{accuracy}%</strong><small>Aniqlik</small></div><div><strong>{errors}</strong><small>Xato</small></div><div><strong>{Math.floor(elapsed/60)}:{String(Math.floor(elapsed%60)).padStart(2,'0')}</strong><small>Vaqt</small></div></div><div className="typing-progress"><i style={{width:`${progress}%`}}/><span>{progress}%</span></div>{isEnglish?<div className="english-learning-card"><div className="english-prompt-head"><span>{game.englishLevel} · TINGLANG VA TO‘LDIRING</span><div><button onClick={()=>listen(.86)}><Volume2/> Qayta tinglash</button><button onClick={()=>listen(.62)}><Headphones/> Sekinroq</button></div></div><h2>{stage.prompt}</h2><p>{stage.translation}</p><div className="vocabulary-row">{stage.words?.map(item=><span key={item.word}><b>{item.word}</b><small>{item.meaning}</small></span>)}</div></div>:<div className="typing-reference" aria-label="Teriladigan matn">{targetChars.map((char,index)=><span className={index<typedChars.length?(typedChars[index]===char?'correct':'wrong'):index===typedChars.length?'cursor':''} key={index}>{char}</span>)}</div>}<label className="typing-input-label">{isEnglish?'Gapni ingliz tilida to‘liq yozing':'Yuqoridagi matnni shu yerga yozing'}<textarea ref={inputRef} spellCheck="false" autoCapitalize="off" autoCorrect="off" value={typed} maxLength={target.length*2+200} onPaste={event=>{event.preventDefault();setPasteBlocked(true)}} onChange={event=>{setTyped(event.target.value);setPasteBlocked(false)}} placeholder={isEnglish?'Masalan: I go to school every day.':'Matnni terishni boshlang…'}/></label>{pasteBlocked&&<p className="typing-warning">Bu mashqda matnni nusxalash mumkin emas. Uni klaviatura orqali tering.</p>}{error&&<p className="form-error" role="alert">{error}</p>}<div className="typing-submit-row"><small>{typed.length} / {target.length} belgi {isEnglish&&<>· yangi so‘z: <b>{stage.focus}</b></>}</small><button className="btn btn-primary" disabled={busy||typed.length<Math.max(1,target.length*(isEnglish ? .65 : .8))} onClick={()=>action('/api/typing/submit',{value:typed})}>{busy?'Tekshirilmoqda…':isEnglish?'Javobni tekshirish':'Natijani tekshirish'} <Check/></button></div></section>}
 </main>
}

function RaceJoin({race,onBack,onStart}){
 const [players,setPlayers]=useState([{name:'',avatar:avatars[0]},{name:'',avatar:avatars[1]}]);const [busy,setBusy]=useState(false);const [error,setError]=useState('');
 const update=(lane,field,value)=>setPlayers(current=>current.map((player,index)=>index===lane?{...player,[field]:value}:player));
 const start=async()=>{if(busy||players.some(player=>!player.name.trim()))return;setBusy(true);setError('');try{await onStart({players:players.map(player=>({...player,name:player.name.trim()}))})}catch(e){setError(e.message)}finally{setBusy(false)}};
 return <div className="join-page race-join-page"><div className="join-top"><button onClick={onBack}><ArrowLeft/></button><Brand light/><span/></div><div className="join-card local-race-join"><div className="join-quiz race-join-banner"><span><Flag/></span><div><small>BITTA KOMPYUTER · 10 TA SAVOL</small><h2>{race.title}</h2><p>Ikki o‘quvchi bitta maydonda yonma-yon bellashadi</p><div className="no-account-badge"><Check size={15}/> Poyga o‘qituvchi tomonidan ochilgan</div></div></div><div className="join-form"><span className="join-step">ISHTIROKCHILAR</span><h1>1v1 poygaga tayyorlaning</h1><p>Har ikki o‘quvchining ismi va avatarini tanlang. To‘g‘ri javob bergan yuguruvchi umumiy maydonda oldinga o‘tadi.</p><div className="local-player-setup">{players.map((player,lane)=><section key={lane}><div><span>{lane+1}</span><b>{lane===0?'1-o‘quvchi':'2-o‘quvchi'}</b></div><label>{lane+1}-o‘quvchi ismi<input value={player.name} onChange={e=>update(lane,'name',e.target.value.slice(0,30))} placeholder={`${lane+1}-o‘quvchi ismi`} autoFocus={lane===0}/></label><label>Avatar<select value={player.avatar} onChange={e=>update(lane,'avatar',e.target.value)}>{avatars.map((value,index)=><option value={value} key={value}>{value} Avatar {index+1}</option>)}</select></label></section>)}</div><button className="btn btn-primary wide join-button" disabled={players.some(player=>!player.name.trim())||busy} onClick={start}>{busy?'Tayyorlanmoqda…':'Poygani boshlash'} <Flag size={19}/></button>{error&&<p className="form-error" role="alert">{error}</p>}</div></div></div>
}

function RaceTrack({race,playerId}){
 const total=Math.max(1,race.questionCount||10);
 const runners=[0,1].map(lane=>{const player=race.racers[lane],winner=race.winnerId===player?.id,progress=Math.min(100,((player?.index||0)/total)*100),running=race.phase==='running'&&!winner;return {lane,player,winner,progress,running}});
 return <section className="shared-race-board" aria-label="Ikki yuguruvchining umumiy poyga maydoni"><div className="shared-race-score">{runners.map(({lane,player,winner})=><article className={`shared-player-card lane-${lane} ${player?.id===playerId?'mine':''} ${winner?'winner':''}`} key={lane}><span>{player?.avatar||'🏁'}</span><div><small>{lane+1}-O‘QUVCHI {player?.id===playerId?'· SIZ':''}</small><b>{player?.name||'Yuguruvchi kutilmoqda'}</b></div><strong>{player?.index||0}<small>/{total}</small></strong></article>)}</div><div className="shared-runner-course"><div className="race-sky" aria-hidden="true"><i/><i/><i/></div><span className="shared-start">START</span><span className="shared-finish">FINISH 🏁</span>{runners.map(({lane,player,winner,progress,running})=><div className={`shared-track-row lane-${lane}`} key={lane}><div className="shared-track-line"/><div className={`shared-track-runner ${running?'is-running':''} ${winner?'is-winner':''}`} style={{left:`clamp(4px, calc(${progress}% - ${progress===100?64:22}px), calc(100% - 66px))`}}><span>{player?.avatar||'🏃'}</span><b>{player?.name||`Yuguruvchi ${lane+1}`}</b></div><div className="shared-runner-status">{winner?'MARRAGA YETDI':race.phase==='running'?'Yugurmoqda':player?.ready?'Startga tayyor':'Kutilmoqda'}</div></div>)}</div></section>
}

function RaceScreen(props){return props.game.localMode?<LocalRaceScreen {...props}/>:<RemoteRaceScreen {...props}/>}

function LocalRaceScreen({game,onUpdate,onLeave}){
 const {race,questions=[],playerIds=[]}=game;const [selected,setSelected]=useState([null,null]);const [busy,setBusy]=useState([false,false]);const [errors,setErrors]=useState(['','']);const [now,setNow]=useState(Date.now());const inflight=useRef([false,false]);
 useEffect(()=>{setSelected([null,null]);setErrors(['',''])},[questions.map(question=>question?.id||'').join('|')]);
 useEffect(()=>{const timer=setInterval(()=>setNow(Date.now()),100);return()=>clearInterval(timer)},[]);
 useEffect(()=>{if(race.phase!=='countdown')return;const delay=Math.max(0,(race.startsAt||Date.now())-Date.now()+80),timer=setTimeout(()=>api('/api/race/session').then(onUpdate).catch(()=>{}),delay);return()=>clearTimeout(timer)},[race.phase,race.startsAt]);
 const answer=async lane=>{if(inflight.current[lane]||selected[lane]===null)return;inflight.current[lane]=true;setBusy(value=>value.map((item,index)=>index===lane?true:item));setErrors(value=>value.map((item,index)=>index===lane?'':item));try{const next=await api('/api/race/answer',{method:'POST',role:'race',data:{playerId:playerIds[lane],questionId:questions[lane]?.id,value:selected[lane]}}),feedback=next.feedbackByPlayer?.[playerIds[lane]];playSound(feedback?.correct?'correct':'wrong');if(next.race.phase==='finished')playSound('finish');onUpdate(next)}catch(error){setErrors(value=>value.map((item,index)=>index===lane?error.message:item))}finally{inflight.current[lane]=false;setBusy(value=>value.map((item,index)=>index===lane?false:item))}};
 const countdown=Math.max(1,Math.ceil(((race.startsAt||now)-now)/1000)),winner=race.racers.find(player=>player.id===race.winnerId);
 return <main className="race-page local-race-page"><header className="race-header"><div><span><Flag/> 1V1 · BITTA MONITOR</span><h1>{race.title}</h1><p>Har bir to‘g‘ri javob yuguruvchini marraga yaqinlashtiradi.</p></div><button className="btn btn-outline" onClick={()=>{if(race.phase==='finished'||confirm('Poygadan chiqishni xohlaysizmi?'))onLeave()}}><ArrowLeft/> Chiqish</button></header><RaceTrack race={race} playerId={null}/>
  {race.phase==='countdown'&&<div className="race-countdown" role="status"><strong>{countdown}</strong><span>HAR IKKI ISHTIROKCHI TAYYOR</span></div>}
  {race.phase==='running'&&<div className="local-question-split">{[0,1].map(lane=>{const player=race.racers.find(item=>item.id===playerIds[lane]),question=questions[lane],feedback=game.feedbackByPlayer?.[playerIds[lane]],retrying=feedback&&!feedback.correct&&feedback.retryAt>now;return <section className={`local-question-lane lane-${lane}`} key={playerIds[lane]}><div className="local-question-title"><span>{player?.avatar}</span><div><small>{lane===0?'CHAP YO‘LAK':'O‘NG YO‘LAK'} · SAVOL {(player?.index||0)+1}/{race.questionCount}</small><b>{player?.name}</b></div></div>{question&&<><h2>{question.text}</h2><div className="local-answer-grid">{question.options.map((option,index)=><button disabled={busy[lane]||retrying} onClick={()=>setSelected(value=>value.map((item,itemIndex)=>itemIndex===lane?index:item))} className={selected[lane]===index?'selected':''} key={index}><span>{String.fromCharCode(65+index)}</span><b>{option}</b></button>)}</div>{feedback&&<p className={`race-feedback ${feedback.correct?'correct':'wrong'}`}>{feedback.correct?'To‘g‘ri — yuguruvchi oldinga chiqdi!':retrying?'Xato. Bir soniyadan keyin yana urinib ko‘ring.':'Yana bir javob tanlang.'}</p>}{errors[lane]&&<p className="form-error" role="alert">{errors[lane]}</p>}<button className="btn btn-primary local-answer-button" disabled={busy[lane]||retrying||selected[lane]===null} onClick={()=>answer(lane)}>{busy[lane]?'Javob tekshirilmoqda…':'Javob berish'} <ChevronRight/></button></>}</section>})}</div>}
  {race.phase==='finished'&&<section className="race-finish winner" role="status"><Trophy/><span>POYGA YAKUNLANDI</span><h2>{winner?.name} g‘olib!</h2><p>U 10 ta savolga birinchi bo‘lib to‘g‘ri javob berdi.</p><button className="btn btn-primary" onClick={onLeave}><Home/> Bosh sahifaga qaytish</button></section>}
 </main>
}

function RemoteRaceScreen({game,onUpdate,onLeave}){
 const {race,playerId,question}=game;const mine=race.racers.find(player=>player.id===playerId);const [selected,setSelected]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[now,setNow]=useState(Date.now());const inflight=useRef(false);
 useEffect(()=>{setSelected(null);setError('')},[question?.id,game.feedback?.at]);
 useEffect(()=>{const timer=setInterval(()=>setNow(Date.now()),100);return()=>clearInterval(timer)},[]);
 useEffect(()=>{if(race.phase!=='countdown')return;const delay=Math.max(0,(race.startsAt||Date.now())-Date.now()+80),timer=setTimeout(()=>api('/api/race/session').then(onUpdate).catch(()=>{}),delay);return()=>clearTimeout(timer)},[playerId,race.phase,race.startsAt]);
 const action=async(path,data)=>{if(inflight.current)return;inflight.current=true;setBusy(true);setError('');try{const next=await api(path,{method:'POST',role:'race',data});if(path.endsWith('/answer'))playSound(next.feedback?.correct?'correct':'wrong');if(next.race.phase==='finished')playSound('finish');onUpdate(next)}catch(e){setError(e.message)}finally{inflight.current=false;setBusy(false)}};
 const countdown=Math.max(1,Math.ceil(((race.startsAt||now)-now)/1000)),retrying=game.feedback&&!game.feedback.correct&&game.feedback.retryAt>now;const winner=race.racers.find(player=>player.id===race.winnerId);
 return <main className="race-page"><header className="race-header"><div><span><Flag/> 1V1 BILIM POYGASI</span><h1>{race.title}</h1><p>Har bir yo‘lakda savollar boshqa tartibda beriladi.</p></div><button className="btn btn-outline" onClick={()=>{if(race.phase==='finished'||confirm('Poygadan chiqishni xohlaysizmi?'))onLeave()}}><ArrowLeft/> Chiqish</button></header><RaceTrack race={race} playerId={playerId}/>
  {race.phase==='lobby'&&<section className="race-stage"><Flag/><h2>{race.racers.length<2?'Ikkinchi yuguruvchi kutilmoqda':'Ikkala yuguruvchi startda'}</h2><p>Har ikki o‘quvchi “Tayyorman”ni bosgach poyga avtomatik boshlanadi.</p><button className="btn btn-primary" disabled={busy||mine?.ready} onClick={()=>action('/api/race/ready')}>{mine?.ready?<><Check/> Siz tayyorsiz</>:<><Flag/> Tayyorman</>}</button></section>}
  {race.phase==='countdown'&&<div className="race-countdown" role="status"><strong>{countdown}</strong><span>STARTGA TAYYOR!</span></div>}
  {race.phase==='running'&&question&&<section className="race-question" key={question.id}><div className="race-question-meta"><span>SAVOL {mine.index+1} / {race.questionCount}</span><b>{question.subject||'Informatika'}</b></div><h2>{question.text}</h2><div className="answer-grid">{question.options.map((option,index)=><button disabled={busy||retrying} onClick={()=>setSelected(index)} className={selected===index?'selected':''} key={index}><span>{String.fromCharCode(65+index)}</span><b>{option}</b></button>)}</div>{game.feedback&&<p className={`race-feedback ${game.feedback.correct?'correct':'wrong'}`}>{game.feedback.correct?'To‘g‘ri! Yuguruvchi oldinga o‘tdi.':retrying?'Xato. Bir soniyadan keyin yana urinib ko‘ring.':'Yana bir javob tanlang.'}</p>}{error&&<p className="form-error" role="alert">{error}</p>}<button className="btn btn-primary race-answer" disabled={busy||retrying||selected===null} onClick={()=>action('/api/race/answer',{questionId:question.id,value:selected})}>{busy?'Javob tekshirilmoqda…':retrying?'Biroz kuting…':'Javob berish'} <ChevronRight/></button></section>}
  {race.phase==='finished'&&<section className={`race-finish ${winner?.id===playerId?'winner':'runner-up'}`} role="status"><Trophy/><span>POYGA YAKUNLANDI</span><h2>{winner?.name} g‘olib!</h2><p>{winner?.id===playerId?'Siz 10 ta savolni birinchi bo‘lib to‘g‘ri yakunladingiz.':'Raqib 10 ta savolni birinchi bo‘lib yakunladi.'}</p><button className="btn btn-primary" onClick={onLeave}><Home/> Bosh sahifaga qaytish</button></section>}
 </main>
}

function PlayQuiz({game,onUpdate}){
  const {quiz,player:current,question:q,index,feedback:grade,deadline,serverNow}=game;
  const checked=!!grade;const [selected,setSelected]=useState(null);const [code,setCode]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [seconds,setSeconds]=useState(Math.max(0,Math.ceil((deadline-serverNow)/1000)));const inflight=useRef(false);const clock=useRef({received:Date.now(),server:serverNow});
  useEffect(()=>{setSelected(null);setCode('');setError('');clock.current={received:Date.now(),server:serverNow};setSeconds(Math.max(0,Math.ceil((deadline-serverNow)/1000)))},[q?.id]);
  useEffect(()=>{if(checked)return;const update=()=>setSeconds(Math.max(0,Math.ceil((deadline-(clock.current.server+Date.now()-clock.current.received))/1000)));const t=setInterval(update,250);return()=>clearInterval(t)},[q?.id,checked,deadline]);
  useEffect(()=>{if(seconds>0&&seconds<=5&&!checked)playSound('tick')},[seconds,checked]);
  const check=async()=>{if(inflight.current||checked)return;inflight.current=true;setBusy(true);setError('');try{const next=await api('/api/play/answer',{method:'POST',role:'player',data:{questionId:q.id,value:q.type==='test'?selected:code}});playSound(next.feedback.ratio>0?'correct':'wrong');onUpdate(next)}catch(e){setError(e.message)}finally{inflight.current=false;setBusy(false)}};
  useEffect(()=>{if(seconds===0&&!checked)check()},[seconds,checked,q?.id]);
  const next=async()=>{if(inflight.current)return;inflight.current=true;setBusy(true);setError('');try{const data=await api('/api/play/next',{method:'POST',role:'player',data:{questionId:q.id}});if(data.finished)playSound('finish');onUpdate(data)}catch(e){setError(e.message)}finally{inflight.current=false;setBusy(false)}};
  if(!q)return null;
  const myRank=Math.max(1,game.ranking.findIndex(p=>p.id===current.id)+1);
  const arenaState=grade?(grade.ratio>0?'correct':'wrong'):'idle';
  return <div className="play-page"><header><div className="play-title">{quiz.title}</div><div className="play-progress"><span>{index+1} / {quiz.questionCount}</span><div><i style={{width:`${((index+1)/quiz.questionCount)*100}%`}}/></div></div><div className="score-pill"><Trophy/> {current.score}</div></header><div className="play-arena"><Arena state={arenaState} compact/><div className="play-arena-copy"><span>BILIM MAYDONI</span><b>{grade?(grade.ratio>0?'Yaxshi natija! Keyingi savolga tayyorlaning.':'Xatoni ko‘rib chiqing va keyingi savolda davom eting.'):'Savolni diqqat bilan o‘qing va javobingizni tanlang.'}</b><small>Har bir javob umumiy ball va reytingga ta’sir qiladi.</small></div></div><main key={q.id} className="question-enter"><div className="question-top"><span className={`q-type ${q.type}`}><Code2/>{questionTypes[q.type]} · {q.subject||quiz.subject}</span><div className={`timer ${seconds<=5?'urgent':''}`} aria-label="Qolgan vaqt"><Clock3/>{seconds}s</div></div><h1>{q.text}</h1>
    {q.type==='test'?<div className="answer-grid">{q.options.map((op,i)=><button disabled={checked||busy} onClick={()=>setSelected(i)} className={`${selected===i?'selected':''} ${checked&&i===grade.correctIndex?'right':''} ${checked&&selected===i&&i!==grade.correctIndex?'wrong':''}`} key={i}><span>{String.fromCharCode(65+i)}</span><b>{op}</b>{selected===i&&<i><Check/></i>}</button>)}</div>:q.type==='shortcut'?<ShortcutInput value={code} onChange={setCode} disabled={checked||busy}/>:<><div className={`code-editor ${q.type==='prompt'?'prompt-editor':''}`}><div className="code-head"><span/><span/><span/><small>{q.type==='prompt'?'Prompt studiyasi':q.subject==='Excel'?'Formula laboratoriyasi':'Amaliy javob'}</small></div><textarea aria-label={q.type==='prompt'?'Prompt javobi':'Amaliy javob'} disabled={checked||busy} spellCheck="false" maxLength={8000} value={code} onChange={e=>setCode(e.target.value)} placeholder={q.type==='prompt'?'Maqsad, auditoriya, kontekst va javob formatini yozing...':'Javobingizni shu yerga yozing...'}/></div>{q.type==='prompt'&&<div className="rubric-hints"><b>Mezonlar</b>{q.criteria.map((c,i)=><span key={i}>{c.label}</span>)}<small>Kalit so‘zlar bo‘yicha mashq bahosi. Mazmunni o‘qituvchi ko‘rib chiqadi.</small></div>}</>}
    {error&&<p className="form-error" role="alert">{error}</p>}
    {!checked?<button className="btn btn-primary check-btn" onClick={check} disabled={busy||(seconds>0&&((q.type==='test'&&selected===null)||(q.type!=='test'&&!code.trim())))}>{busy?'Yuborilmoqda…':seconds===0?'Natijani olish':'Javobni yuborish'} <ChevronRight/></button>:<><div className={`feedback ${grade.ratio>0?'success':'failure'}`} role="status"><div className="feedback-icon">{grade.ratio>0?<Check/>:<X/>}</div><div><h3>{grade.expired?'Vaqt tugadi':grade.correct?'Ajoyib! To‘g‘ri javob':grade.ratio>0?'Mezonlarning bir qismi bajarildi':'Bu safar xato'}</h3><p>+{current.lastEarned} ball</p></div><div className="mini-rank"><Medal/><span>Hozirgi o‘rin<b>{myRank}-o‘rin</b></span></div><button className="btn btn-primary" disabled={busy} onClick={next}>{busy?'Yuklanmoqda…':index===quiz.questionCount-1?'Yakunlash':'Keyingi savol'} <ChevronRight/></button></div><div className="answer-explanation">{q.type!=='test'&&<p><b>Namuna javob:</b> {grade.answer}</p>}{grade.explanation&&<p>{grade.explanation}</p>}{grade.checks.map((c,i)=><span className={c.passed?'criterion-pass':'criterion-fail'} key={i}>{c.passed?'✓':'○'} {c.label}</span>)}</div></>}
  </main></div>
}

function Result({quiz,player,db,onHome}){
  const rows=rankRows(db.players.filter(p=>p.quizId===quiz.id));const rank=rows.findIndex(p=>p.id===player.id)+1||1;const icons=['🥇','🥈','🥉'];
  return <div className="result-page"><Celebration/><div className="confetti c1">◆</div><div className="confetti c2">●</div><div className="confetti c3">▲</div><Brand light/><div className="result-layout"><Arena state="victory" compact label="TEST YAKUNLANDI"/><div className="result-card"><div className="result-avatar"><Avatar3D value={player.avatar} large/><i>{icons[rank-1]||<Medal/>}</i></div><div className="eyebrow"><Sparkles/> TEST YAKUNLANDI</div><h1>Barakalla, {player.name}!</h1><p>“{quiz.title}” testini muvaffaqiyatli yakunladingiz.</p><div className="result-rank"><small>SIZNING O‘RNINGIZ</small><strong>{rank}<sup>-o‘rin</sup></strong></div><div className="result-stats"><div><Trophy/><span><b>{player.score}</b>Jami ball</span></div><div><Check/><span><b>{player.correct} / {quiz.questions.length}</b>To‘g‘ri javob</span></div><div><Zap/><span><b>{Math.round(player.score/Math.max(1,quiz.questions.length))}</b>O‘rtacha ball</span></div></div><button className="btn btn-primary wide" onClick={onHome}><Home/> Bosh sahifaga qaytish</button></div></div></div>
}

export default App;
